/* Copy a C string to the clipboard as CF_TEXT */
void CopyText(HWND hwnd, char FAR *text)
{
    HGLOBAL hMem;
    char FAR *p;
    int len;

    len = lstrlen(text) + 1;
    hMem = GlobalAlloc(GMEM_MOVEABLE, len);
    if (!hMem)
        return;
    p = GlobalLock(hMem);
    lstrcpy(p, text);
    GlobalUnlock(hMem);

    if (OpenClipboard(hwnd)) {
        EmptyClipboard();
        SetClipboardData(CF_TEXT, hMem);   /* ownership passes to Windows */
        CloseClipboard();
    } else {
        GlobalFree(hMem);                  /* open failed: free it ourselves */
    }
}

void PasteText(HWND hwnd, char FAR *buf, int buflen)
{
    HGLOBAL hMem;
    char FAR *p;

    if (!IsClipboardFormatAvailable(CF_TEXT))
        return;
    if (!OpenClipboard(hwnd))
        return;
    hMem = GetClipboardData(CF_TEXT);
    if (hMem) {
        p = GlobalLock(hMem);
        if (p) {
            /* copy out; leave the block locked only briefly */
            lstrcpyn(buf, p, buflen);
            GlobalUnlock(hMem);
        }
    }
    CloseClipboard();
}

